CURLcode Curl_auth_create_plain_message(struct Curl_easy *data,
                                        const char *userp,
                                        const char *passwdp,
                                        char **outptr,
                                        size_t *outlen)
{
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t plain_len = user_len + 1 + pass_len;
  size_t b64_len;
  char *plain = NULL;
  char *b64 = NULL;
  CURLcode result = CURLE_OUT_OF_MEMORY;

  if((user_len + 1 + pass_len) != plain_len)
    return CURLE_BAD_FUNCTION_ARGUMENT;

  plain = malloc(plain_len);
  if(!plain)
    goto error;

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);

  b64_len = Curl_base64_encode(data, plain, plain_len, &b64, FALSE);
  if(!b64)
    goto error;

  *outptr = b64;
  *outlen = b64_len;
  result = CURLE_OK;

error:
  free(plain);
  return result;
}

CURLcode Curl_auth_plain_message(struct Curl_easy *data, const char *userp,
                                 const char *passwdp, char **outptr, size_t *outlen)
{
  size_t userlen = strlen(userp);
  size_t passlen = strlen(passwdp);
  size_t length = 2 + userlen + passlen;
  size_t size = 4 * ((length + 2) / 3); /* Base64 encoded size */
  char *buffer;
  CURLcode result;

  /* Check for overflow in length calculations */
  if(length != 2 + userlen + passlen)
    return CURLE_OUT_OF_MEMORY;

  buffer = calloc(1, size);
  if(!buffer)
    return CURLE_OUT_OF_MEMORY;

  /* Construct the PLAIN message */
  memcpy(buffer, userp, userlen);
  memcpy(buffer + userlen, passwdp, passlen);

  /* Encode the message in Base64 */
  result = Curl_base64_encode(data, buffer, length, outptr, outlen);
  free(buffer);

  return result;
}

CURLcode generate_plain_auth_message(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t userlen = strlen(userp);
  size_t passlen = strlen(passwdp);
  size_t plain_len = userlen + 1 + passlen;
  size_t b64_len = Curl_base64_encode(data, NULL, 0, plain_len, NULL);

  if (b64_len == 0)
    return CURLE_OUT_OF_MEMORY;

  char *b64 = (char *)Curl_safefree(*outptr);
  *outptr = b64 = (char *)malloc(b64_len);
  if (!b64)
    return CURLE_OUT_OF_MEMORY;

  char *plain = (char *)malloc(plain_len);
  if (!plain) {
    free(b64);
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, userlen);
  plain[userlen] = '\0';
  memcpy(plain + userlen + 1, passwdp, passlen);

  CURLcode result = Curl_base64_encode(data, plain, plain_len, b64, &b64_len);
  if (result != CURLE_OK) {
    free(plain);
    free(b64);
    *outptr = NULL;
    return result;
  }

  free(plain);
  *outlen = b64_len - 1; // Exclude the trailing null byte

  return CURLE_OK;
}

CURLcode auth_plain_message(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t user_len = strlen(userp);
  size_t pass_len = strlen(passwdp);
  size_t plain_len = user_len + 1 + pass_len;
  size_t b64_len = Curl_base64_encode(data, NULL, plain_len, NULL);
  char *plain = NULL;
  char *b64 = NULL;
  CURLcode result = CURLE_OK;

  if (!userp || !passwdp || !outptr || !outlen) {
    return CURLE_BAD_FUNCTION_ARGUMENT;
  }

  if (SIZE_MAX - 3 < user_len + pass_len) {
    return CURLE_OUT_OF_MEMORY;
  }

  plain = malloc(plain_len + 1);
  if (!plain) {
    return CURLE_OUT_OF_MEMORY;
  }

  memcpy(plain, userp, user_len);
  plain[user_len] = '\0';
  memcpy(plain + user_len + 1, passwdp, pass_len);
  plain[plain_len + 1] = '\0';

  b64 = malloc(b64_len);
  if (!b64) {
    free(plain);
    return CURLE_OUT_OF_MEMORY;
  }

  result = Curl_base64_encode(data, plain, plain_len + 1, &b64, outlen);
  if (result != CURLE_OK) {
    free(plain);
    free(b64);
    return result;
  }

  free(plain);
  *outptr = b64;
  return CURLE_OK;
}

CURLcode base64_plain_auth(struct Curl_easy *data, const char *userp, const char *passwdp, char **outptr, size_t *outlen) {
  size_t userlen = strlen(userp);
  size_t passlen = strlen(passwdp);
  size_t total_len = userlen + 1 + passlen;
  size_t b64_len = Curl_base64_encode(data, "", 0, outptr, NULL);
  char *plain;
  CURLcode result;

  if (userlen == 0 || passlen == 0) {
    return CURLE_BAD_FUNCTION_ARGUMENT;
  }

  if (total_len > SIZE_MAX / 3) {
    return CURLE_OUT_OF_MEMORY;
  }

  plain = malloc(total_len);
